def _t():
    t = time.mktime((1973, 9, 16, 1, 3, 52, 0, 0, -1))
    assert time.ctime(t) == 'Sun Sep 16 01:03:52 1973', ('assertEqual', time.ctime(t), 'Sun Sep 16 01:03:52 1973')
    t = time.mktime((2000, 1, 1, 0, 0, 0, 0, 0, -1))
    assert time.ctime(t) == 'Sat Jan  1 00:00:00 2000', ('assertEqual', time.ctime(t), 'Sat Jan  1 00:00:00 2000')
    for year in [-100, 100, 1000, 2000, 2050, 10000]:
        try:
            testval = time.mktime((year, 1, 10) + (0,) * 6)
        except (ValueError, OverflowError):
            pass
        else:
            assert time.ctime(testval)[20:] == str(year), ('assertEqual', time.ctime(testval)[20:], str(year))
